-- AI Workspace schema foundation. Runtime, providers, queues, and auth must be configured separately.
CREATE TABLE IF NOT EXISTS ai_workspaces (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','deleting')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ai_workspace_members (workspace_id UUID NOT NULL REFERENCES ai_workspaces(id) ON DELETE CASCADE, user_id TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('owner','administrator','developer','agent_manager','operator','viewer')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS ai_model_providers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES ai_workspaces(id) ON DELETE CASCADE, provider_key TEXT NOT NULL, display_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'not_configured' CHECK (status IN ('not_configured','testing','active','suspended')), credentials_ref TEXT, supported_models JSONB NOT NULL DEFAULT '[]', last_tested_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(workspace_id,provider_key));
CREATE TABLE IF NOT EXISTS ai_agents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES ai_workspaces(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', category TEXT NOT NULL, avatar TEXT, system_instructions TEXT NOT NULL DEFAULT '', primary_objective TEXT NOT NULL DEFAULT '', language TEXT NOT NULL DEFAULT 'English', response_style TEXT NOT NULL DEFAULT 'Professional', knowledge_base_ids JSONB NOT NULL DEFAULT '[]', approved_tools JSONB NOT NULL DEFAULT '[]', provider_id UUID REFERENCES ai_model_providers(id), model_name TEXT, temperature NUMERIC(4,3), max_output_tokens INTEGER, lifecycle TEXT NOT NULL DEFAULT 'draft' CHECK (lifecycle IN ('draft','configured','testing','active','paused','archived')), created_by TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ai_workflows (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES ai_workspaces(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','testing','published','paused','archived')), nodes JSONB NOT NULL DEFAULT '[]', edges JSONB NOT NULL DEFAULT '[]', created_by TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ai_knowledge_bases (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES ai_workspaces(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'empty' CHECK (status IN ('empty','ingesting','indexed','failed','archived')), retention_policy TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ai_knowledge_documents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), knowledge_base_id UUID NOT NULL REFERENCES ai_knowledge_bases(id) ON DELETE CASCADE, source_name TEXT NOT NULL, source_type TEXT NOT NULL, storage_ref TEXT, status TEXT NOT NULL DEFAULT 'uploaded' CHECK (status IN ('uploaded','extracting','chunking','embedding','indexed','failed','removal_requested','removed')), checksum TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ai_integrations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES ai_workspaces(id) ON DELETE CASCADE, integration_key TEXT NOT NULL, display_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'not_connected' CHECK (status IN ('not_connected','connecting','connected','error','disconnected')), permissions JSONB NOT NULL DEFAULT '[]', credential_ref TEXT, last_tested_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(workspace_id,integration_key));
CREATE TABLE IF NOT EXISTS ai_approvals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES ai_workspaces(id) ON DELETE CASCADE, agent_id UUID REFERENCES ai_agents(id), workflow_id UUID REFERENCES ai_workflows(id), action_type TEXT NOT NULL, proposed_action JSONB NOT NULL, risk_level TEXT NOT NULL CHECK (risk_level IN ('low','medium','high','critical')), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','changes_requested','expired')), decided_by TEXT, decided_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ai_execution_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES ai_workspaces(id) ON DELETE CASCADE, agent_id UUID REFERENCES ai_agents(id), workflow_id UUID REFERENCES ai_workflows(id), event_type TEXT NOT NULL, status TEXT NOT NULL, duration_ms INTEGER, input_tokens INTEGER, output_tokens INTEGER, provider_key TEXT, error_code TEXT, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ai_memory_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES ai_workspaces(id) ON DELETE CASCADE, agent_id UUID REFERENCES ai_agents(id), scope TEXT NOT NULL CHECK (scope IN ('short_term','long_term','organization','user')), subject_ref TEXT, content_ref TEXT NOT NULL, retention_until TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ai_usage_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES ai_workspaces(id) ON DELETE CASCADE, agent_id UUID REFERENCES ai_agents(id), provider_key TEXT, model_name TEXT, input_tokens INTEGER, output_tokens INTEGER, duration_ms INTEGER, estimated_cost_minor BIGINT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ai_audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES ai_workspaces(id), actor_id TEXT, actor_role TEXT, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS ai_agents_workspace_lifecycle_idx ON ai_agents(workspace_id,lifecycle,created_at DESC);
CREATE INDEX IF NOT EXISTS ai_workflows_workspace_status_idx ON ai_workflows(workspace_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS ai_execution_workspace_created_idx ON ai_execution_events(workspace_id,created_at DESC);
CREATE INDEX IF NOT EXISTS ai_usage_workspace_created_idx ON ai_usage_events(workspace_id,created_at DESC);
CREATE INDEX IF NOT EXISTS ai_audit_workspace_created_idx ON ai_audit_logs(workspace_id,created_at DESC);
ALTER TABLE ai_workspaces ENABLE ROW LEVEL SECURITY; ALTER TABLE ai_workspace_members ENABLE ROW LEVEL SECURITY; ALTER TABLE ai_model_providers ENABLE ROW LEVEL SECURITY; ALTER TABLE ai_agents ENABLE ROW LEVEL SECURITY; ALTER TABLE ai_workflows ENABLE ROW LEVEL SECURITY; ALTER TABLE ai_knowledge_bases ENABLE ROW LEVEL SECURITY; ALTER TABLE ai_knowledge_documents ENABLE ROW LEVEL SECURITY; ALTER TABLE ai_integrations ENABLE ROW LEVEL SECURITY; ALTER TABLE ai_approvals ENABLE ROW LEVEL SECURITY; ALTER TABLE ai_execution_events ENABLE ROW LEVEL SECURITY; ALTER TABLE ai_memory_records ENABLE ROW LEVEL SECURITY; ALTER TABLE ai_usage_events ENABLE ROW LEVEL SECURITY; ALTER TABLE ai_audit_logs ENABLE ROW LEVEL SECURITY;
-- No public policies. All workspace reads, writes, provider operations, approvals, and logs require authenticated server-side authorization.
